export function getPageForVerse(surah, verse) {
  // Iterate backwards to find the page where the verse started
  for (let i = PAGE_MAP.length - 1; i >= 0; i--) {
    const entry = PAGE_MAP[i];
    if (surah > entry.surah || (surah === entry.surah && verse >= entry.verse)) {
      return entry.page;
    }
  }
  return 1;
}

export function getVerseRangeForPage(page) {
  if (page < 1 || page > 604) return null;
  const start = PAGE_MAP[page - 1];
  const end = PAGE_ENDS[page - 1];
  return {
    startSurah: start.surah,
    startVerse: start.verse,
    endSurah: end.surah,
    endVerse: end.verse
  };
}
